mapper.sql:
WHERE p.plan_type = #{planType}
AND p.partner_code = #{partnerCode}
AND COALESCE(d.network, pv.network) = #{network}
AND COALESCE(d.name, pv.name) ILIKE '%' || #{q} || '%'

    AND p.status = 'PUBLISHED' AND d.id IS NULL
    AND p.status NOT IN ('ENDED', 'HIDDEN') AND d.id IS NOT NULL AND d.publish_at IS NULL
    AND p.status NOT IN ('ENDED', 'HIDDEN') AND d.publish_at IS NOT NULL
    AND p.status = 'ENDED'
    AND p.status = 'HIDDEN'

mapper.update:
UPDATE plan SET status = CASE WHEN published_version_id IS NOT NULL THEN 'PUBLISHED' ELSE 'PENDING' END,
                ended_on = NULL, updated_at = now()
WHERE id = #{planId}
